const tabs=await (await fetch('http://127.0.0.1:9222/json')).json(); const t=tabs.find(x=>x.type==='page'&&x.url.startsWith('https://pakthai-ai-sourcing.pakthaitech.workers.dev/')); if(!t) throw new Error('Owner-authenticated Worker dashboard tab not found'); const ws=new WebSocket(t.webSocketDebuggerUrl); let finished=false; const cities=['Faisalabad','Lahore','Karachi','Islamabad','Rawalpindi','Peshawar','Multan','Gujranwala','Sialkot','Quetta','Hyderabad']; const expr=`(async()=>{const cities=${JSON.stringify(cities)};const out=[];for(let i=0;i<cities.length;i+=3){const batch=cities.slice(i,i+3);try{const r=await fetch('/api/buyer-prospects/discover',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({cities:batch,searches:['computer hardware retailer']})});const body=await r.json();out.push({cities:batch,http_status:r.status,body});}catch(e){out.push({cities:batch,error:String(e)})}}return JSON.stringify({nationwide_discovery:true,market:'Pakistan',search:'computer hardware retailer',batches:out})})()`; ws.addEventListener('open',()=>ws.send(JSON.stringify({id:1,method:'Runtime.evaluate',params:{expression:expr,awaitPromise:true,returnByValue:true,userGesture:true}}))); ws.addEventListener('message',e=>{const m=JSON.parse(String(e.data));if(m.id===1){finished=true;console.log('NATIONWIDE_DISCOVERY_RESULT',m.result?.result?.value??JSON.stringify(m));ws.close()}}); ws.addEventListener('error',e=>{console.log('CDP_ERROR',String(e));process.exitCode=1});setTimeout(()=>{if(!finished){console.log('NATIONWIDE_DISCOVERY_WAIT_TIMEOUT');ws.close()}},180000);